-- Synthetic PostgreSQL fixtures only. Never run in hosted Supabase.
begin;
create temporary table provider_assertions(name text primary key);
grant insert on provider_assertions to authenticated,anon,service_role;
create function pg_temp.provider_check(ok boolean,name text) returns void language plpgsql as $$ begin
 if ok is distinct from true then raise exception 'Provider test assertion failed: %',name; end if;
 insert into provider_assertions values(name); end $$;
select set_config('test.provider.operation',(select operation_id::text from public.fiscal_documents limit 1),true);
select set_config('test.provider.batch',(select batch_id::text from public.fiscal_operations where id=current_setting('test.provider.operation')::uuid),true);
select set_config('test.provider.tenant',(select tenant_id::text from public.fiscal_operations where id=current_setting('test.provider.operation')::uuid),true);
select set_config('test.provider.actor',(select owner_user_id::text from public.tenants where id=current_setting('test.provider.tenant')::uuid),true);
select set_config('test.provider.other',(select owner_user_id::text from public.tenants where id<>current_setting('test.provider.tenant')::uuid limit 1),true);
select set_config('test.provider.request',gen_random_uuid()::text,true);
select set_config('test.provider.fiscal_count',(select count(*)::text from public.fiscal_operations),true);
select pg_temp.provider_check(not has_function_privilege('service_role','private.begin_invoice_email_before_provider_tests(uuid,uuid,text[],text,text,boolean,text)','execute'),'legacy helper cannot bypass shared exclusion');
select pg_temp.provider_check(not has_function_privilege('anon','public.email_provider_test_report()','execute'),'anonymous cannot read reports');
set role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.provider.actor'))::text,true);
do $$ begin
 begin perform public.request_email_provider_tests(current_setting('test.provider.actor')::uuid,current_setting('test.provider.request')::uuid,'owner@example.com');raise exception 'Client requested directly';exception when insufficient_privilege then perform pg_temp.provider_check(true,'request server only');end;
 begin perform * from private.email_provider_tests;raise exception 'Private data readable';exception when insufficient_privilege then perform pg_temp.provider_check(true,'private leases not readable');end;
 begin perform public.claim_email_provider_test();raise exception 'Client claimed';exception when insufficient_privilege then perform pg_temp.provider_check(true,'claim server only');end;
end $$;
reset role;
set role service_role;
do $$ begin
 begin perform public.request_email_provider_tests(gen_random_uuid(),gen_random_uuid(),'owner@example.com');raise exception 'Unknown actor queued';exception when insufficient_privilege then perform pg_temp.provider_check(true,'unknown actor refused');end;
 begin perform public.request_email_provider_tests(current_setting('test.provider.actor')::uuid,gen_random_uuid(),E'owner@example.com\nBcc:other@example.com');raise exception 'Header injection';exception when invalid_parameter_value then perform pg_temp.provider_check(true,'destination injection refused');end;
end $$;
select pg_temp.provider_check(public.request_email_provider_tests(current_setting('test.provider.actor')::uuid,current_setting('test.provider.request')::uuid,'owner@example.com'),'request three tests');
select pg_temp.provider_check(public.request_email_provider_tests(current_setting('test.provider.actor')::uuid,current_setting('test.provider.request')::uuid,'owner@example.com'),'same request idempotent');
select pg_temp.provider_check(not public.request_email_provider_tests(current_setting('test.provider.actor')::uuid,gen_random_uuid(),'owner@example.com'),'new request daily limit');
do $$ begin
 begin perform public.request_email_provider_tests(current_setting('test.provider.actor')::uuid,current_setting('test.provider.request')::uuid,'other@example.com');raise exception 'Request changed';exception when invalid_parameter_value then perform pg_temp.provider_check(true,'request cannot change target');end;
end $$;
reset role;
select pg_temp.provider_check((select count(*)=3 from private.email_provider_tests),'one job per provider');
set role authenticated;
select pg_temp.provider_check(jsonb_array_length(public.email_provider_test_report())=3,'owner sees tests');
select pg_temp.provider_check(public.email_provider_test_report()::text !~ 'token|payload_sha256|sender|provider_id','report does not expose private intent');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.provider.other'))::text,true);
select pg_temp.provider_check(public.email_provider_test_report()='[]'::jsonb,'other tenant sees no tests');
reset role;
set role service_role;
select set_config('test.provider.job',public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(current_setting('test.provider.job')::jsonb->>'provider'='brevo','fixed first provider');
select pg_temp.provider_check(public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid) is null,'next provider waits for previous test');
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,gen_random_uuid(),'notes@example.com',repeat('a',64)) is null,'wrong token cannot send');
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64))->>'provider'='brevo','provider test intent');
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64)) is null,'single intent for test');
select public.enable_invoice_email(current_setting('test.provider.actor')::uuid,current_setting('test.provider.batch')::uuid);
select set_config('test.provider.invoice',public.claim_invoice_email(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(public.begin_invoice_email((current_setting('test.provider.invoice')::jsonb->>'id')::uuid,(current_setting('test.provider.invoice')::jsonb->>'token')::uuid,array['mailjet'],'owner@example.com','notes@example.com',true,repeat('b',64))->>'waiting'='true','invoice waits for active test even on another provider');
select pg_temp.provider_check(public.finish_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,gen_random_uuid(),'accepted','synthetic')=false,'wrong finish token');
select pg_temp.provider_check(public.finish_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'accepted','synthetic'),'accepted test finished');
select pg_temp.provider_check(not public.finish_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'accepted','synthetic'),'finish cannot commit twice');
reset role;
select pg_temp.provider_check((select count(*)=1 from private.invoice_email_attempts where provider='brevo'),'test counts in shared quota ledger');
update public.invoice_email_deliveries set next_run_at=now();
set role service_role;
select set_config('test.provider.invoice',public.claim_invoice_email(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(public.begin_invoice_email((current_setting('test.provider.invoice')::jsonb->>'id')::uuid,(current_setting('test.provider.invoice')::jsonb->>'token')::uuid,array['mailjet'],'owner@example.com','notes@example.com',true,repeat('b',64))->>'provider'='mailjet','invoice may start after finished test');
select set_config('test.provider.job',public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64))->>'waiting'='true','test waits for invoice active on another provider');
select pg_temp.provider_check(public.finish_invoice_email((current_setting('test.provider.invoice')::jsonb->>'id')::uuid,(current_setting('test.provider.invoice')::jsonb->>'token')::uuid,'accepted','synthetic-invoice'),'invoice completion releases exclusion');
reset role;
update private.email_provider_tests set next_run_at=now() where provider='sendpulse';
-- Invoice traffic already set the SendPulse clock; the independent test must wait.
update private.invoice_email_providers set next_allowed_at=now()+interval '75 seconds' where provider='sendpulse';
set role service_role;
select set_config('test.provider.job',public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(current_setting('test.provider.job')::jsonb->>'provider'='sendpulse','second test is SendPulse');
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64))->>'waiting'='true','SendPulse respects existing 75 second interval');
reset role;
select pg_temp.provider_check((select count(*)=0 from private.invoice_email_attempts where provider='sendpulse'),'waiting consumes no quota');
update private.invoice_email_providers set next_allowed_at=now() where provider='sendpulse';
update private.email_provider_tests set next_run_at=now() where provider='sendpulse';
set role service_role;
select set_config('test.provider.job',public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64))->>'provider'='sendpulse','SendPulse intent after release');
reset role;
select pg_temp.provider_check((select next_allowed_at>=now()+interval '75 seconds' from private.invoice_email_providers where provider='sendpulse'),'test persists SendPulse interval');
set role service_role;
select pg_temp.provider_check(public.finish_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'network_uncertain'),'uncertain acceptance persisted');
select set_config('test.provider.job',public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(current_setting('test.provider.job')::jsonb->>'provider'='mailjet','separate third provider test is not a retry');
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64))->>'waiting'='true','Mailjet test respects preceding invoice interval');
reset role;
-- now() is fixed inside this disposable transaction; advance only the synthetic clocks.
update private.invoice_email_providers set next_allowed_at=now() where provider='mailjet';
update private.email_provider_tests set next_run_at=now() where provider='mailjet';
set role service_role;
select set_config('test.provider.job',public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64))->>'provider'='mailjet','Mailjet intent');
reset role;
-- Crash after intent: observation expires to uncertain, never dispatch again.
update private.email_provider_tests set lease_until=now()-interval '1 second' where provider='mailjet';
set role service_role;
select pg_temp.provider_check(public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid) is null,'expired intended test is never reclaimed');
reset role;
select pg_temp.provider_check((select status='uncertain' from private.email_provider_tests where provider='mailjet'),'expired send becomes uncertain');
select pg_temp.provider_check((select count(*)=3 from private.invoice_email_attempts where provider_test_id is not null),'exactly three intents total');
select pg_temp.provider_check((select count(*)::text=current_setting('test.provider.fiscal_count') from public.fiscal_operations),'no new fiscal operations');
select pg_temp.provider_check((select status='authorized' and transmit_count=1 from public.fiscal_operations where id=current_setting('test.provider.operation')::uuid),'fiscal authorization preserved');
-- Shared cap includes real delivery attempts; test has no special quota bypass.
update private.email_provider_tests set created_at=now()-interval '25 hours';
update private.invoice_email_providers set next_allowed_at=now(),busy_until=now(),paused_until=now();
insert into private.invoice_email_attempts(delivery_id,provider) select (current_setting('test.provider.invoice')::jsonb->>'id')::uuid,'brevo' from generate_series(1,299);
set role service_role;
select pg_temp.provider_check(public.request_email_provider_tests(current_setting('test.provider.actor')::uuid,gen_random_uuid(),'owner@example.com'),'new daily test later');
select set_config('test.provider.job',public.claim_email_provider_test(current_setting('test.provider.tenant')::uuid)::text,true);
select pg_temp.provider_check(public.begin_email_provider_test((current_setting('test.provider.job')::jsonb->>'id')::uuid,(current_setting('test.provider.job')::jsonb->>'token')::uuid,'notes@example.com',repeat('a',64))->>'waiting'='true','shared cap includes invoice plus test traffic');
reset role;
select pg_temp.provider_check((select count(*)=300 from private.invoice_email_attempts where provider='brevo'),'full cap creates no extra attempt');
select 'PROVIDER_TEST_ASSERTIONS='||count(*) from provider_assertions;
rollback;
